import test from 'node:test';
import assert from 'node:assert/strict';
import { testServer } from './helpers.js';
async function fixture(run) {
  const server = await testServer();
  try {
    const api = server.agent();
    await api('POST', '/auth/signup', { name: 'Workflow owner', email: 'workflow@impact.test', password: 'correct-horse-battery' });
    const org = (await api('POST', '/orgs', { name: 'Workflow impact' })).data.organization;
    const project = (await api('POST', '/orgs/' + org.id + '/projects', { key: 'FLOW', name: 'Workflow' })).data.project;
    await run({ api, project, server });
  } finally { await server.close(); }
}
test('workflow impact returns canonical per-status counts and stable identifiers', () => fixture(async ({ api, project }) => {
  await api('POST', '/projects/' + project.id + '/issues', { title: 'Active', statusId: project.statuses[1].id });
  const value = (await api('GET', '/projects/' + project.id + '/workflow')).data;
  assert.deepEqual(value.usage.map(row => row.issueCount), [0, 1, 0]);
  assert.deepEqual(value.usage.map(row => row.statusId), project.statuses.map(row => row.id));
  assert.equal(value.project.revision, (await api('GET', '/projects/' + project.id)).data.project.revision);
}));
test('a concurrent board move invalidates an earlier workflow impact decision', () => fixture(async ({ api, project }) => {
  const issue = (await api('POST', '/projects/' + project.id + '/issues', { title: 'Move me' })).data.issue;
  const before = (await api('GET', '/projects/' + project.id)).data.project;
  await api('POST', '/issues/' + issue.id + '/move', { statusId: project.statuses[1].id });
  const statuses = project.statuses.map(({ id, name, category }) => ({ id, name, category })); statuses[1].category = 'done';
  const stale = await api('PUT', '/projects/' + project.id + '/workflow', { statuses, expectedRevision: before.revision });
  assert.equal(stale.status, 409); assert.notEqual(stale.data.error.details.current.workflowUsageRevision, before.workflowUsageRevision);
  assert.equal((await api('GET', '/projects/' + project.id + '/workflow')).data.statuses[1].category, 'active');
}));
test('confirmed category changes reuse canonical issue and sprint ledger updates', () => fixture(async ({ api, project }) => {
  const issue = (await api('POST', '/projects/' + project.id + '/issues', { title: 'Deliver', statusId: project.statuses[1].id, estimate: 5 })).data.issue;
  const sprint = (await api('POST', '/projects/' + project.id + '/sprints', { name: 'Delivery', startDate: '2026-10-01', endDate: '2026-10-20' })).data.sprint;
  await api('POST', '/sprints/' + sprint.id + '/issues', { issueIds: [issue.id] });
  const before = (await api('GET', '/projects/' + project.id)).data.project;
  const statuses = before.statuses.map(({ id, name, category }) => ({ id, name, category })); statuses[1].category = 'done';
  const changed = await api('PUT', '/projects/' + project.id + '/workflow', { statuses, expectedRevision: before.revision });
  assert.equal(changed.status, 200); assert.equal(changed.data.statuses[1].id, issue.statusId);
  assert.equal((await api('GET', '/sprints/' + sprint.id)).data.sprint.remainingPoints, 0);
  assert.equal((await api('GET', '/sprints/' + sprint.id + '/burndown')).data.days.find(day => day.date === new Date().toISOString().slice(0, 10)).remaining, 0);
}));

import test from 'node:test';
import assert from 'node:assert/strict';
import { createAttachmentQueue } from '../src/pages/work/attachment-queue.js';
import { reviewWorkflow } from '../src/pages/work/workflow-review.js';
const file = (name, size = 3) => ({ name, size });
const deferred = () => { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; };
test('attachment queue starts one streamed file at a time and preserves each hash result', async () => {
  const calls = [], saves = [], gates = [deferred(), deferred()];
  const queue = createAttachmentQueue({ issueId: 'resource', maxBytes: 10, upload: request => { const index = calls.length; calls.push(request); return gates[index].promise; }, onSaved: value => saves.push(value.id) });
  queue.add([file('first'), file('second')]); const running = queue.start();
  assert.equal(calls.length, 1); assert.equal(calls[0].file.name, 'first');
  gates[0].resolve({ attachment: { id: 'one', sha256: 'a'.repeat(64) } }); await Promise.resolve(); await Promise.resolve();
  assert.equal(calls.length, 2); gates[1].resolve({ attachment: { id: 'two', sha256: 'b'.repeat(64) } }); await running;
  assert.deepEqual(saves, ['one', 'two']); assert.deepEqual(queue.snapshot().entries.map(entry => entry.status), ['succeeded', 'succeeded']);
  assert.equal(queue.snapshot().entries[0].result.sha256, 'a'.repeat(64)); queue.dispose();
});
test('failed file stays failed and only an explicit retry queues a new attempt', async () => {
  let calls = 0;
  const queue = createAttachmentQueue({ issueId: 'resource', maxBytes: 10, upload: async () => { calls++; if (calls === 1) throw new Error('connection uncertain'); return { attachment: { id: 'saved' } }; } });
  queue.add([file('one')]); await queue.start(); await queue.start();
  assert.equal(calls, 1); assert.equal(queue.snapshot().entries[0].status, 'failed');
  queue.retry(queue.snapshot().entries[0].id); await queue.start();
  assert.equal(calls, 2); assert.equal(queue.snapshot().entries[0].attempts.length, 2); queue.dispose();
});
test('cancel aborts current file and pauses untouched pending files until deliberate resume', async () => {
  const calls = [];
  const queue = createAttachmentQueue({ issueId: 'resource', maxBytes: 10, upload: request => new Promise((resolve, reject) => { calls.push(request); request.signal.addEventListener('abort', () => reject(Object.assign(new Error('cancelled'), { code: 'CANCELLED' }))); }) });
  queue.add([file('one'), file('two')]); const run = queue.start(); queue.cancel(); await run;
  assert.equal(calls.length, 1); assert.deepEqual(queue.snapshot().entries.map(entry => entry.status), ['cancelled', 'pending']);
  assert.equal(queue.snapshot().paused, true); assert.equal(queue.snapshot().running, false); queue.dispose();
});
test('resource disposal aborts old queue and suppresses late progress success and finally', async () => {
  const gate = deferred(), states = []; let request;
  const queue = createAttachmentQueue({ issueId: 'old', maxBytes: 10, notify: state => states.push(state), upload: value => { request = value; return gate.promise; } });
  queue.add([file('old')]); const run = queue.start(); queue.dispose(); const count = states.length;
  assert.equal(request.signal.aborted, true); request.onProgress({ loaded: 3, total: 3 }); gate.resolve({ attachment: { id: 'late' } }); await run;
  assert.equal(states.length, count);
  const current = createAttachmentQueue({ issueId: 'new', maxBytes: 10, upload: async () => ({ attachment: { id: 'new' } }) });
  current.add([file('new')]); await current.start(); assert.equal(current.snapshot().entries[0].result.id, 'new'); current.dispose();
});
test('queue validates every file before attempts and supports zero byte files', async () => {
  const sent = [];
  const queue = createAttachmentQueue({ issueId: 'resource', maxBytes: 3, upload: async request => { sent.push(request.file.name); return { attachment: { id: request.file.name } }; } });
  queue.add([file('too-big', 4), file('../bad'), file('empty', 0)]); await queue.start();
  assert.deepEqual(sent, ['empty']); assert.deepEqual(queue.snapshot().entries.map(entry => entry.status), ['invalid', 'invalid', 'succeeded']);
  queue.clearFinished(); assert.equal(queue.snapshot().entries.length, 0); queue.dispose();
});
const base = [{ id: 'todo', name: 'Todo', category: 'todo' }, { id: 'active', name: 'Doing', category: 'active' }, { id: 'done', name: 'Done', category: 'done' }];
test('workflow review preserves IDs and shows exact recategorized issue counts', () => {
  const draft = base.map(status => status.id === 'active' ? { ...status, category: 'done' } : status);
  const review = reviewWorkflow(base, draft, [{ statusId: 'active', issueCount: 7 }]);
  assert.equal(review.blocked, false); assert.equal(review.needsDecision, true);
  assert.deepEqual(review.rows.find(row => row.id === 'active'), { id: 'active', name: 'Doing', previousCategory: 'active', nextCategory: 'done', nextName: 'Doing', issueCount: 7, removed: false, recategorized: true });
});
test('workflow review blocks occupied removal and exposes usable per-row duplicate errors', () => {
  const review = reviewWorkflow(base, base.filter(status => status.id !== 'active'), [{ statusId: 'active', issueCount: 2 }]);
  assert.equal(review.occupiedRemoval, true); assert.equal(review.blocked, true);
  const duplicate = reviewWorkflow(base, base.map(status => ({ ...status, name: 'Duplicate' })));
  assert.ok(duplicate.errors.some(error => error.index === 0)); assert.ok(duplicate.errors.some(error => error.index === 1));
});
test('workflow review permits unused removal and rejects alien or duplicated stable IDs', () => {
  assert.equal(reviewWorkflow(base, base.filter(status => status.id !== 'active')).blocked, false);
  assert.equal(reviewWorkflow(base, [{ ...base[0], id: 'foreign' }, base[2]]).blocked, true);
  assert.equal(reviewWorkflow(base, [base[0], { ...base[2], id: 'todo' }]).blocked, true);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { testServer } from '../../server/test/helpers.js';
import { createIssue } from '../../server/src/modules/work/issues.js';
async function browser(mode) {
  const server = await testServer(); let child;
  try {
    const api = server.agent();
    const auth = await api('POST', '/auth/signup', { name: 'Planning browser', email: 'planning-browser@example.test', password: 'correct-horse-battery' });
    const org = (await api('POST', '/orgs', { name: 'Planning browser' })).data.organization;
    const project = (await api('POST', '/orgs/' + org.id + '/projects', { key: 'PLAN', name: 'First planning project' })).data.project;
    const other = (await api('POST', '/orgs/' + org.id + '/projects', { key: 'NEXT', name: 'Second planning project' })).data.project;
    const issues = Array.from({ length: 24 }, (_, n) => createIssue(server.ctx, { user: auth.data.user }, project.id, { title: 'Planning issue ' + String(n).padStart(2, '0'), estimate: 3 }));
    const secondIssue = createIssue(server.ctx, { user: auth.data.user }, other.id, { title: 'Other resource issue' });
    const sprint = (await api('POST', '/projects/' + project.id + '/sprints', { name: 'First sprint', startDate: '2026-10-01', endDate: '2026-10-20' })).data.sprint;
    const next = (await api('POST', '/projects/' + project.id + '/sprints', { name: 'Next sprint', startDate: '2026-10-21', endDate: '2026-10-30' })).data.sprint;
    const settings = { mode, url: server.url, cookie: auth.cookie, projectId: project.id, otherId: other.id, issueId: issues[0].id, secondCard: issues[1].id, otherIssueId: secondIssue.id, activeId: project.statuses[1].id, sprintId: sprint.id, nextSprintId: next.id };
    const result = await new Promise((resolve, reject) => {
      child = spawn('/usr/bin/python3', [fileURLToPath(new URL('./planning-browser.py', import.meta.url)), JSON.stringify(settings)], { detached: true });
      let stdout = '', stderr = '';
      const timer = setTimeout(() => { try { process.kill(-child.pid, 'SIGKILL'); } catch {} reject(new Error('Planning browser exceeded 55 seconds')); }, 55000);
      child.stdout.on('data', value => stdout += value); child.stderr.on('data', value => stderr += value);
      child.on('error', error => { clearTimeout(timer); reject(error); });
      child.on('close', code => { clearTimeout(timer); resolve({ code, stdout, stderr }); });
    });
    assert.equal(result.code, 0, result.stderr + result.stdout); assert.equal(JSON.parse(result.stdout.trim()).ok, true);
    if (mode === 'planning') {
      const moved = (await api('GET', '/issues/' + issues[0].id)).data.issue;
      const ordered = (await api('GET', '/projects/' + project.id + '/board')).data.columns.find(column => column.status.id === project.statuses[1].id).issues;
      assert.equal(moved.statusId, project.statuses[1].id); assert.deepEqual(ordered.map(issue => issue.id), [issues[1].id, issues[0].id]);
      assert.equal((await api('GET', '/sprints/' + sprint.id)).data.sprint.status, 'active');
    } else if (mode === 'upload') {
      const oldFiles = (await api('GET', '/issues/' + issues[0].id + '/attachments')).data.items;
      const newFiles = (await api('GET', '/issues/' + secondIssue.id + '/attachments')).data.items;
      assert.ok(oldFiles.some(file => file.name === 'old-resource.txt'));
      assert.ok(newFiles.some(file => file.name === 'new-resource.txt'));
    } else {
      const oldFiles = (await api('GET', '/issues/' + issues[0].id + '/attachments')).data.items;
      const newFiles = (await api('GET', '/issues/' + secondIssue.id + '/attachments')).data.items;
      assert.ok(oldFiles.some(file => file.name === 'queue-first.txt'));
      assert.ok(oldFiles.some(file => file.name === 'queue-second.txt'));
      assert.deepEqual(newFiles.map(file => file.name), ['queue-new-resource.txt']);
    }
  } finally { if (child?.pid) { try { process.kill(-child.pid, 'SIGKILL'); } catch {} } await server.close(); }
}
for (const mode of ['planning', 'upload', 'queue']) test('pinned browser planning ' + mode + ' preserves resource lifecycle', { timeout: 65000 }, () => browser(mode));
